(3610436, 503641, 34134, '<td valign="top">Creative and well done. Like the colors.</td>', 'Creative and well done. Like the colors.', '2007-05-03 12:41:16.000000', NULL, 1),
(3610447, 505497, 34134, '<td valign="top">Nice concept, but for my taste the flowers should be sharper and the building level.</td>', 'Nice concept, but for my taste the flowers should be sharper and the building level.', '2007-05-03 12:44:26.000000', NULL, 1),
