(3615251, 504268, 43774, '<td valign="top">This is gorgeous!</td>', 'This is gorgeous!', '2007-05-04 15:15:43.000000', NULL, 1),
(3615252, 505602, 43774, '<td valign="top">Wonderful clear photo, grat job.</td>', 'Wonderful clear photo, grat job.', '2007-05-04 15:15:55.000000', NULL, 1),
(3615253, 493619, 43774, '<td valign="top">Very nice, beautiful colours in the sky.</td>', 'Very nice, beautiful colours in the sky.', '2007-05-04 15:16:08.000000', NULL, 1),
