(3621682, 500220, 41047, '<td valign="top">nice processing and tones.</td>', 'nice processing and tones.', '2007-05-06 20:24:40.000000', NULL, 1),
(3621684, 505390, 36309, '<td valign="top">I''m sure the light is natural, but at first sight it looks too orange, which lessens the impact of the photo</td>', 'I''m sure the light is natural, but at first sight it looks too orange, which lessens the impact of the photo', '2007-05-06 20:25:18.000000', NULL, 1),
