(3621689, 502564, 41047, '<td valign="top">very interesting composition.</td>', 'very interesting composition.', '2007-05-06 20:26:18.000000', NULL, 1),
(3621692, 505285, 41047, '<td valign="top">i like to watch the interaction between these two indivituals, the man not getting closer while he''s talking, looks interesting. i like the light a lot as well, nice play of light and shadows.</td>', 'i like to watch the interaction between these two indivituals, the man not getting closer while he''s talking, looks interesting. i like the light a lot as well, nice play of light and shadows.', '2007-05-06 20:28:15.000000', NULL, 1),
(3621699, 497663, 41047, '<td valign="top">love this, quite funny and cute :) very nice dof and love the dark sky in the background.</td>', 'love this, quite funny and cute :) very nice dof and love the dark sky in the background.', '2007-05-06 20:29:38.000000', NULL, 1),
