(3621720, 505476, 41047, '<td valign="top">i love this, the composition is fantastic and great processing. the tones are lovely.</td>', 'i love this, the composition is fantastic and great processing. the tones are lovely.', '2007-05-06 20:34:36.000000', NULL, 1),
(3621722, 505252, 41047, '<td valign="top">i like the colour composition in this. pretty cool processing.</td>', 'i like the colour composition in this. pretty cool processing.', '2007-05-06 20:35:51.000000', NULL, 1),
(3621727, 505438, 41047, '<td valign="top">i love the composition and the tones, great job.</td>', 'i love the composition and the tones, great job.', '2007-05-06 20:37:36.000000', NULL, 1),
